        self.ctx, self.stream, self.tool_choice = ctx, stream, tool_choice


def build_runtime(ctx: RuntimeContext, stream: bool = False, tool_choice: str = "auto") -> Runtime:
    return Runtime(ctx, stream, tool_choice)

