import importlib.metadata


def pinned_version(package):
    # Try to get the runtime version from the installed package
    try:
        # Use importlib.metadata for Python >=3.8
        version = importlib.metadata.version(package)
        parts = version.split(".")
        # version might have extra suffixes like "0.29.1" -> ["0", "29", "1"]
        # parse numeric parts only
        nums = []
        for part in parts[:3]:
            # remove any non-digit suffix
            num_part = ""
            for ch in part:
                if ch.isdigit():
                    num_part += ch
                else:
                    break
            if num_part:
                nums.append(int(num_part))
            else:
                nums.append(0)
        while len(nums) < 3:
            nums.append(0)
        return tuple(nums[:3])
    except importlib.metadata.PackageNotFoundError:
        pass
    # Fallback to parsing requirements.txt
