import re
import pkg_resources


def pinned_version(package):
    # Look for exact pin (==) or lower bound (>=) for the package
    for line in Path("requirements.txt").read_text().splitlines():
        # Strip comments and whitespace
        line = line.split('#')[0].strip()
        if not line:
            continue
        # Match patterns like "httpx==0.29.1" or "httpx>=0.29.1"
        # Allow optional extras or version specifiers
        match = re.match(r'^\s*([a-zA-Z0-9_-]+)\s*([=<>!~]=)\s*([0-9]+\.[0-9]+\.[0-9]+)', line)
        if match:
            pkg, op, ver = match.groups()
            if pkg.strip() == package.strip():
                # For >=, we need to return the lower bound version
                # For ==, return that version
                parts = list(map(int, ver.split('.')))
                # Pad to at least 3 parts
                while len(parts) < 3:
                    parts.append(0)
                return tuple(parts)
    # Fallback: try to import the package and get its version
    try:
        import httpx
        # Parse version string like "0.29.1"
        ver = pkg_resources.parse_version(httpx.__version__)
        parts = []
        for part in ver.split("."):
            try:
                parts.append(int(part))
            except ValueError:
                # handle non-numeric parts like 'post', 'dev', etc.
                # take only numeric prefix
                num_part = ""
                for ch in part:
                    if ch.isdigit():
                        num_part += ch
                    else:
                        break
                if num_part:
                    parts.append(int(num_part))
                else:
                    parts.append(0)
        # Pad to at least 3 parts
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts[:3])
